<?php
session_start();
if (!isset($_SESSION['username'])) { header('Location: login_admin.php'); exit; }
require_once __DIR__.'/koneksi.php';
$uploadDir=__DIR__.'/uploads/site/'; $uploadWeb='uploads/site/'; if(!is_dir($uploadDir)) @mkdir($uploadDir,0775,true);
function program_upload(string $field,string $old=''): string { global $uploadDir,$uploadWeb; if(!isset($_FILES[$field])||$_FILES[$field]['error']!==UPLOAD_ERR_OK)return $old; $ext=strtolower(pathinfo($_FILES[$field]['name'],PATHINFO_EXTENSION)); if(!in_array($ext,['jpg','jpeg','png','webp'],true)||!@getimagesize($_FILES[$field]['tmp_name'])||(int)$_FILES[$field]['size']>4*1024*1024)return $old; $name='program_'.date('YmdHis').'_'.bin2hex(random_bytes(3)).'.'.$ext; return move_uploaded_file($_FILES[$field]['tmp_name'],$uploadDir.$name)?$uploadWeb.$name:$old; }
$msg=''; $edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??''; $id=(int)($_POST['id']??0);
 if($action==='save'){
  $nama=trim($_POST['nama']??'');$des=trim($_POST['deskripsi']??'');$kat=trim($_POST['kategori']??'');$icon=trim($_POST['icon']??'fa-laptop-code');$sort=(int)($_POST['sort_order']??0);$status=($_POST['status']??'Aktif')==='Aktif'?'Aktif':'Nonaktif';
  $old='';if($id){$r=mysqli_query($koneksi,'SELECT gambar FROM site_programs WHERE id='.$id);$old=$r?((mysqli_fetch_assoc($r)['gambar']??'')):'';}
  $gambar=program_upload('gambar',$old);
  if($nama){if($id){$st=mysqli_prepare($koneksi,'UPDATE site_programs SET nama=?,deskripsi=?,kategori=?,icon=?,gambar=?,sort_order=?,status=? WHERE id=?');mysqli_stmt_bind_param($st,'sssssisi',$nama,$des,$kat,$icon,$gambar,$sort,$status,$id);}else{$st=mysqli_prepare($koneksi,'INSERT INTO site_programs(nama,deskripsi,kategori,icon,gambar,sort_order,status) VALUES(?,?,?,?,?,?,?)');mysqli_stmt_bind_param($st,'sssssis',$nama,$des,$kat,$icon,$gambar,$sort,$status);}if($st){mysqli_stmt_execute($st);mysqli_stmt_close($st);$msg=$id?'Program keahlian diperbarui.':'Program keahlian ditambahkan.';}}
 }
 if($action==='delete'&&$id){mysqli_query($koneksi,'DELETE FROM site_programs WHERE id='.$id);$msg='Program keahlian dihapus.';}
}
if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$r=mysqli_query($koneksi,'SELECT * FROM site_programs WHERE id='.$id);$edit=$r?mysqli_fetch_assoc($r):null;}
$rows=[];$q=mysqli_query($koneksi,'SELECT * FROM site_programs ORDER BY sort_order ASC,id ASC');while($q&&($r=mysqli_fetch_assoc($q)))$rows[]=$r;
?>
