<div class="cms-grid" style="margin-top:18px">
<div class="cms-card"><div class="cms-card-head"><div><span><?= $edit?'EDIT DATA':'DATA BARU' ?></span><h3><?= $edit?'Edit Program Keahlian':'Tambah Program Keahlian' ?></h3></div><i class="fa-solid fa-graduation-cap"></i></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="cms-form-grid"><label class="full">Nama Program<input required name="nama" value="<?=htmlspecialchars($edit['nama']??'')?>"></label><label>Kategori<input name="kategori" value="<?=htmlspecialchars($edit['kategori']??'Teknologi & Keahlian')?>"></label><label>Ikon Font Awesome<input name="icon" value="<?=htmlspecialchars($edit['icon']??'fa-laptop-code')?>"></label><label class="full">Deskripsi<textarea name="deskripsi" rows="5"><?=htmlspecialchars($edit['deskripsi']??'')?></textarea></label><label>Urutan<input type="number" name="sort_order" value="<?= (int)($edit['sort_order']??count($rows)+1) ?>"></label><label>Status<select name="status"><option <?=($edit['status']??'Aktif')==='Aktif'?'selected':''?>>Aktif</option><option <?=($edit['status']??'')==='Nonaktif'?'selected':''?>>Nonaktif</option></select></label><label class="full">Gambar<input type="file" name="gambar" accept="image/*"><small>Opsional, JPG/PNG/WEBP maksimal 4 MB.</small></label></div><div style="display:flex;gap:8px;margin-top:15px"><button class="cms-save" type="submit"><i class="fa-solid fa-floppy-disk"></i> Simpan</button><?php if($edit): ?><a class="btn-admin" href="admin_program.php" style="background:#e8edf4;color:#172033!important">Batal</a><?php endif; ?></div></form></div>
<div class="cms-card"><div class="cms-card-head"><div><span>PREVIEW DATA</span><h3>Program yang Tersimpan</h3></div><i class="fa-solid fa-layer-group"></i></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Program</th><th>Kategori</th><th>Status</th><th style="width:150px">Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=htmlspecialchars($r['nama'])?></strong><small style="display:block;color:#727b8a;margin-top:3px"><?=htmlspecialchars($r['deskripsi'])?></small></td><td><?=htmlspecialchars($r['kategori'])?></td><td><span class="status-pill <?=strtolower($r['status'])==='aktif'?'status-active':'status-offline'?>"><?=htmlspecialchars($r['status'])?></span></td><td><div class="action-wrapper"><a class="action-btn btn-edit" href="admin_program.php?edit=<?=(int)$r['id']?>"><i class="fa-solid fa-pen"></i><span>Edit</span></a><form method="post" style="display:inline" onsubmit="return confirm('Hapus program ini?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="action-btn btn-delete" type="submit"><i class="fa-solid fa-trash"></i><span>Hapus</span></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div>
